fn is_prime(n: i8) -> bool {
    // By definition, primes are integers >= 2 with no divisors other than 1 and themselves.
    if n < 2 {
        return false;
    }

    // Try every possible divisor from 2 up to n - 1.
    let mut divisor: i8 = 2;
    while divisor < n {
        // If we find any k in [2, n) dividing n, it's not prime.
        if n % divisor == 0 {
            return false;
        }
        divisor += 1;
    }

    // No divisors found ⇒ n is prime.
    true
}

